 ctx.fillStyle='#496b6e';ctx.beginPath();ctx.moveTo(0,H*.31);for(let x=0;x<=W+20;x+=50)ctx.lineTo(x,H*(.27+Math.sin(x*.009+t*.12)*.018+Math.cos(x*.023)*.008));ctx.lineTo(W,H*.42);ctx.lineTo(0,H*.42);ctx.fill();
