 for(let x=8;x<W;x+=20){ctx.fillStyle=['#df7e63','#e8d2a4','#7bb79e','#9a8db4'][Math.floor(x/20)%4];ctx.globalAlpha=.72;ctx.fillRect(x,H*.26+(Math.sin(x*.12)*2),3,H*.022);ctx.globalAlpha=1}
 const water=ctx.createLinearGradient(0,H*.34,0,H);water.addColorStop(0,'#337b88');water.addColorStop(.4,'#1c6376');water.addColorStop(1,'#0c344b');ctx.fillStyle=water;ctx.fillRect(0,H*.34,W,H*.66);
 // shimmering horizontal water strokes
