 // lane ropes and buoys
 for(let lane=0;lane<5;lane++){const y=H*(.405+lane*.084);ctx.globalAlpha=.24;ctx.strokeStyle='#d6e5d5';ctx.setLineDash([5,8]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.72;const shift=(t*80+lane*31)%48;for(let x=-50+shift;x<W+45;x+=48){ctx.fillStyle=lane===2?'#ffdd83':'#eaf0d7';ctx.beginPath();ctx.ellipse(x,y,3,2.1,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
}
function drawBoat(x,y,scale,color,phase,own=false){
 ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);
 const wiggle=Math.sin(elapsed*8+phase)*1.5;
 // wake
 ctx.globalAlpha=.18;ctx.strokeStyle='#e4f2dc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-44,wiggle+7);ctx.lineTo(-86,wiggle+10);ctx.moveTo(-42,wiggle+11);ctx.lineTo(-66,wiggle+16);ctx.stroke();ctx.globalAlpha=1;
 // shell
 ctx.fillStyle='#071e2b';ctx.beginPath();ctx.moveTo(-48,wiggle+2);ctx.quadraticCurveTo(-3,wiggle+9,48,wiggle+1);ctx.lineTo(62,wiggle);ctx.lineTo(49,wiggle+6);ctx.quadraticCurveTo(0,wiggle+13,-49,wiggle+5);ctx.closePath();ctx.fill();
 ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-40,wiggle+1);ctx.quadraticCurveTo(0,wiggle+5,46,wiggle+1);ctx.lineTo(54,wiggle);ctx.quadraticCurveTo(4,wiggle+8,-42,wiggle+3);ctx.fill();
 // rower body and head
 const rx=2+Math.sin(elapsed*7+phase)*2;ctx.strokeStyle='#f0d7bd';ctx.lineWidth=3.4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(rx,wiggle-1);ctx.lineTo(rx-3,wiggle-10);ctx.stroke();ctx.fillStyle=own?'#f4d079':'#f0cbb0';ctx.beginPath();ctx.arc(rx-4,wiggle-14,4.2,0,Math.PI*2);ctx.fill();
 ctx.strokeStyle=own?'#f9e3a1':'#d9d8c8';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(rx-1,wiggle-5);ctx.lineTo(rx+14+Math.cos(elapsed*7+phase)*6,wiggle+3);ctx.stroke();
