 if(own){ctx.fillStyle='#fff4c2';ctx.font='800 8px system-ui';ctx.textAlign='center';ctx.fillText('YOU',3,wiggle-22)}
 ctx.restore();
}
function draw(t=performance.now()/1000){if(!W||!H)return;ctx.clearRect(0,0,W,H);drawBackground(t);
 const lanes=[...bots.map((b,i)=>({p:b.p,color:b.color,phase:b.phase,own:false,lane:i})),{p:progress,color:'#e6f4ee',phase:4.7,own:true,lane:2}].sort((a,b)=>a.lane-b.lane);
 const scale=clamp(W/650,.62,1);const mid=W*.49;
 for(const boat of lanes){const rel=boat.p-progress;let x=mid+rel*W*1.65; x=clamp(x,-85,W+85);const y=H*(.405+boat.lane*.084);drawBoat(x,y,scale,boat.color,boat.phase,boat.own);
