 // finish gate glides closer as distance falls
 const dist=1-progress;const gateX=mid+dist*W*1.55; if(gateX<W+30){ctx.save();ctx.globalAlpha=clamp(1-dist*1.2,.25,1);const y1=H*.37,y2=H*.77;ctx.strokeStyle='#f2e7c4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(gateX,y1);ctx.lineTo(gateX,y2);ctx.moveTo(gateX+18,y1);ctx.lineTo(gateX+18,y2);ctx.stroke();for(let n=0;n<6;n++){ctx.fillStyle=n%2?'#173248':'#f4df9b';ctx.fillRect(gateX+n*3,y1-1,3,8)}ctx.fillStyle='#fff0b0';ctx.font='800 7px system-ui';ctx.textAlign='center';ctx.fillText('FINISH',gateX+9,y1-5);ctx.restore()}
 // floating lane flag markers
 const markerX=W*.06;ctx.save();ctx.globalAlpha=.65;for(let i=0;i<5;i++){const y=H*(.405+i*.084);ctx.fillStyle='#f4dd9e';ctx.fillRect(markerX,y-13,1,13);ctx.fillStyle=i===2?'#ffdc7f':'#e7e8d4';ctx.beginPath();ctx.moveTo(markerX+1,y-12);ctx.lineTo(markerX+10,y-9);ctx.lineTo(markerX+1,y-6);ctx.fill()}ctx.restore();
 if(strokeFlash>0){ctx.globalAlpha=strokeFlash*2;ctx.fillStyle='#ffe18a';ctx.beginPath();ctx.arc(mid,H*.57,18+(1-strokeFlash)*35,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 if(shake>0){/* slight impact ripple for a repeated-side mistake */ctx.globalAlpha=shake;ctx.strokeStyle='#ff8978';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(mid,H*.57,30+(1-shake)*30,7+(1-shake)*9,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
}
resize();
})();
</script>
